const frames = $input.first().json.session.route_details.frames || [];

const items = [];

for (const frame of frames) {
  let img_b64 = frame.imagebase64 || frame.image_base64; // handle either key
  if (img_b64) {
    if (!img_b64.startsWith('data:image')) {
      img_b64 = 'data:image/jpeg;base64,' + img_b64;
    }

    // push one item per frame
    items.push({
      json: {
        image: img_b64,
        // optional: keep metadata from frame if you want
        frame_index: frame.index ?? undefined,
        frame_id: frame.id ?? undefined,
      }
    });
  }
}

return items;

