// Helper: normalize angle to [-180, 180] degrees
function normalizeAngleDeg(angle) {
  while (angle > 180) angle -= 360;
  while (angle < -180) angle += 360;
  return angle;
}

const poses = $input.item.json.poses || [];
const instructions = [];

let previousBearing = null;

for (let i = 0; i < poses.length - 1; i++) {
  const C = poses[i];
  const F = poses[i + 1];

  const dx = F.x - C.x;
  const dy = F.y - C.y;
  const distance = Math.sqrt(dx * dx + dy * dy);

  // Bearing of displacement vector C→F
  const currentBearing = Math.atan2(dy, dx) * 180 / Math.PI;

  // Turn needed
  let turn_to_walk = 0;
  if (i === 0) {
    // First step: turn from initial yaw to first displacement bearing
    turn_to_walk = normalizeAngleDeg(currentBearing - C.yaws);
  } else {
    // Subsequent steps: bearing change from previous segment
    turn_to_walk = normalizeAngleDeg(currentBearing - previousBearing);
  }

  // Final orientation turn (only at destination)
  const isLastFrame = (i === poses.length - 2);
  const turn_at_dest = isLastFrame 
    ? normalizeAngleDeg(F.yaws - currentBearing)
    : 0;

  instructions.push({
    from_frame_index: i,
    to_frame_index: i + 1,
    from_frame_id: C.frame_id,
    to_frame_id: F.frame_id,
    turn_to_walk: turn_to_walk,
    walk_distance: distance,
    turn_at_dest: turn_at_dest,
    is_final_step: isLastFrame
  });

  previousBearing = currentBearing;
}

return [{ json: { instructions } }];

// Get frames list from RTAB-MAP route details
const frames = $input.first().json.session.route_details.frames || [];

// Build an ordered array of poses (we'll keep index/id + pose)
const poses = [];

for (let i = 0; i < frames.length; i++) {
  const frame = frames[i];
  const pos = frame.position || {};
  const orient = frame.orientation || {};

  const x = pos.x;
  const y = pos.y;
  const yaws = orient.yaw;

  // If position is missing, skip this frame
  // --> ADD YAW HERE
  if (x === undefined || y === undefined || yaws === undefined) {
    continue;
  }

  poses.push({
    frame_index: i,
    frame_id: frame.frame_id ?? frame.id ?? null,
    x: Number(x),
    y: Number(y),
    yaws: Number(yaws) // radians
  });
}

// Return a single item with all poses in order
return [
  {
    json: {
      poses
    }
  }
];

const instructions = $input.item.json.instructions || [];
const MIN_TURN_DEG = 15;
const segments = [];

for (const inst of instructions) {
  const turn1 = inst.turn_to_walk;
  const dist = inst.walk_distance;
  const turn2 = inst.turn_at_dest;

  // Add alignment turn (if significant)
  if (Math.abs(turn1) >= MIN_TURN_DEG) {
    segments.push({
      type: 'turn',
      angle: turn1,
      from_frame_index: inst.from_frame_index,
      from_frame_id: inst.from_frame_id
    });
  }

  // Add walk
  if (dist > 0.1) {
    segments.push({
      type: 'walk',
      distance: dist,
      from_frame_index: inst.from_frame_index,
      to_frame_index: inst.to_frame_index,
      from_frame_id: inst.from_frame_id,
      to_frame_id: inst.to_frame_id
    });
  }

  // Add final orientation turn (only at destination)
  if (inst.is_final_step && Math.abs(turn2) >= MIN_TURN_DEG) {
    segments.push({
      type: 'turn',
      angle: turn2,
      from_frame_index: inst.to_frame_index,
      from_frame_id: inst.to_frame_id,
      is_final_orientation: true
    });
  }
}

return [{ json: { segments } }];

// Get frames list from RTAB-MAP route details
const frames = $input.first().json.session.complete_path_coordinates || [];

// Build an ordered array of poses (we'll keep index/id + pose)
const poses = [];

for (let i = 0; i < frames.length; i++) {
  const frame = frames[i];

  const x = frame.x;
  const y = frame.y;
  const yaws = frame.yaw;

  // If position is missing, skip this frame
  if (x === undefined || y === undefined || yaws === undefined) {
    continue;
  }

  poses.push({
    frame_index: i,
    frame_id: frame.frame_id ?? null,
    x: Number(x),
    y: Number(y),
    yaws: Number(yaws) // radians
  });
}

// Return a single item with all poses in order
return [
  {
    json: {
      poses
    }
  }
];

// Find the first significant turn: junction
function normalizeAngleDeg(angle) {
  while (angle > 180) angle -= 360;
  while (angle < -180) angle += 360;
  return angle;
}

const poses = $input.first().json.poses || [];
const JUNCTION_THRESHOLD = 15; // degrees - significant turn

if (poses.length < 2) {
  return [{ json: { next_junction: null, message: "No path available" } }];
}

const current = poses[0];
let previousBearing = null;
let junctionFound = false;
let nextJunction = null;

for (let i = 0; i < poses.length - 1; i++) {
  const C = poses[i];
  const F = poses[i + 1];

  const dx = F.x - C.x;
  const dy = F.y - C.y;
  const distance = Math.sqrt(dx * dx + dy * dy);
  const currentBearing = Math.atan2(dy, dx) * 180 / Math.PI;

  let turnAngle = 0;

  if (i === 0) {
    // Initial turn from current facing to first displacement
    turnAngle = normalizeAngleDeg(currentBearing - C.yaws);
  } else if (previousBearing !== null) {
    // Turn between consecutive segments
    turnAngle = normalizeAngleDeg(currentBearing - previousBearing);
  }

  // Check if this is a junction (significant turn or final destination)
  const isLastFrame = (i === poses.length - 2);
  const isJunction = Math.abs(turnAngle) >= JUNCTION_THRESHOLD || isLastFrame;

  if (isJunction && !junctionFound) {
    // This is the next junction
    const finalTurn = isLastFrame ? normalizeAngleDeg(F.yaws - currentBearing) : 0;

    nextJunction = {
      junction_frame_index: i + 1,
      junction_frame_id: F.frame_id,
      distance_to_junction: distance,
      turn_before_junction: turnAngle,
      turn_at_junction: finalTurn,
      is_final_destination: isLastFrame,
      junction_position: { x: F.x, y: F.y }
    };
    junctionFound = true;
    break;
  }

  previousBearing = currentBearing;
}

// If no junction found, just walk to destination
if (!nextJunction) {
  const last = poses[poses.length - 1];
  const dx = last.x - current.x;
  const dy = last.y - current.y;
  const distance = Math.sqrt(dx * dx + dy * dy);

  nextJunction = {
    junction_frame_index: poses.length - 1,
    junction_frame_id: last.frame_id,
    distance_to_junction: distance,
    turn_before_junction: 0,
    turn_at_junction: 0,
    is_final_destination: true,
    junction_position: { x: last.x, y: last.y }
  };
}

return [{ json: { next_junction: nextJunction } }];

// Immediate Instruction
const junctionData = $input.first().json.next_junction;

if (!junctionData) {
  return [{ json: { instruction: "No navigation data available" } }];
}

const dist = junctionData.distance_to_junction.toFixed(1);
const turn = Math.round(junctionData.turn_before_junction);
const direction = turn > 0 ? "left" : "right";
const absTurn = Math.abs(turn);

let instruction = "";

if (junctionData.is_final_destination) {
  if (absTurn >= 15) {
    instruction = `Walk ${dist} meters, then turn ${direction} ${absTurn}° to reach your destination.`;
  } else {
    instruction = `Walk straight ${dist} meters to reach your destination.`;
  }

  const finalTurn = Math.round(junctionData.turn_at_junction);
  if (Math.abs(finalTurn) >= 15) {
    const finalDir = finalTurn > 0 ? "left" : "right";
    instruction += ` Turn ${finalDir} ${Math.abs(finalTurn)}° to face the object.`;
  }
} else {
  if (absTurn >= 15) {
    instruction = `Walk ${dist} meters, then turn ${direction} ${absTurn}°.`;
  } else {
    instruction = `Walk straight ${dist} meters.`;
  }
}

return [{
  json: {
    instruction: instruction,
    junction_position: junctionData.junction_position,
    distance_to_junction: junctionData.distance_to_junction,
    junction_frame_id: junctionData.junction_frame_id
  }
}];

