const fireworksContent = $json.choices[0].message.content;
const parsed = JSON.parse(fireworksContent);
return {
  all_detections: parsed.all_detections, 
  bbox: parsed.all_detections[0]?.bbox || [],
  depth: parsed.all_detections[0]?.depth || 0,
  confidence: parsed.all_detections[0]?.confidence || 0};

// Parse STRING bbox back to ARRAY + convert all to numbers
const session = $input.first().json.session;
const bboxString = session.bbox;  // "[346,419,499,555]"
const scaleXString = session.scale_x;  // "3.2097"
const scaleYString = session.scale_y;  // "3.2637"

// 🔧 FIX 1: Parse bbox string → number array
const bbox = JSON.parse(bboxString);  // [346, 419, 499, 555]
const scale_x = parseFloat(scaleXString) || 1;  // 3.2097
const scale_y = parseFloat(scaleYString) || 1;  // 3.2637

// 🔧 FIX 2: Parse other numeric strings
const depth = parseFloat(session.depth) || 0;
const confidence = parseFloat(session.confidence) || 0;

// ✅ PERFECT bbox scaling
const scaled_bbox = bbox.length === 4 ? [
  Math.round(bbox[0] * scale_x),  // x1 * 3.2097
  Math.round(bbox[1] * scale_y),  // y1 * 3.2637
  Math.round(bbox[2] * scale_x),  // x2 * 3.2097
  Math.round(bbox[3] * scale_y)   // y2 * 3.2637
] : [];

return [{
  json: {
    // Original (Fireworks coords)
    fireworks_bbox: bbox,
    fireworks_depth: depth,
    fireworks_confidence: confidence,

    // ✅ SCALED for original image
    scaled_bbox: scaled_bbox,
    scaled_depth: depth,
    scaled_confidence: confidence,

    // hset compatible (use scaled!)
    bbox: scaled_bbox,
    depth: depth,
    confidence: confidence,

    // Debug
    scaling_info: {
      scale_x: scale_x,
      scale_y: scale_y,
      before_scaling: bboxString,
      after_scaling: scaled_bbox
    }
  }
}];

