// Get complete path coordinates (not frames!)
const pathCoords = $input.first().json.session.complete_path_coordinates || [];

// Return first (current) and last (target) coordinates
if (pathCoords.length === 0) {
  throw new Error('No path coordinates available');
}

const firstPose = pathCoords[0];
const lastPose = pathCoords[pathCoords.length - 1];

return [
  {
    json: {
      type: "current_location",
      x: Number(firstPose.x),
      y: Number(firstPose.y),
      yaw: Number(firstPose.yaw)
    }
  },
  {
    json: {
      type: "target_object_location", 
      x: Number(lastPose.x),
      y: Number(lastPose.y),
      yaw: Number(lastPose.yaw)
    }
  }
];

// Get path coordinates from Path node (handles new format)
const pathData = $input.first().json;
const poses = pathData.shortest_path;  // Array of {coordinate_index, x, y, type}

if (!poses || poses.length < 2) {
  return [{json: { 
    error: 'No valid path found', 
    path_length: poses?.length || 0,
    debug: pathData 
  }}];
}

// Convert string coordinates to numbers
const numericPoses = poses.map(p => ({
  ...p,
  x: parseFloat(p.x),
  y: parseFloat(p.y)
}));

const instructions = [];

for (let i = 0; i < numericPoses.length - 1; i++) {
  const C = numericPoses[i];     // Current waypoint
  const F = numericPoses[i + 1]; // Forward waypoint

  const dx = F.x - C.x;
  const dy = F.y - C.y;
  const distance = Math.sqrt(dx * dx + dy * dy);

  // Bearing of displacement vector C→F (degrees)
  const currentBearing = Math.atan2(dy, dx) * 180 / Math.PI;

  // Turn needed from previous bearing
  let turn_to_walk = 0;
  if (i === 0) {
    // First step: turn from current position to first segment
    turn_to_walk = currentBearing;
  } else {
    // Subsequent steps: turn from previous segment bearing
    const prevBearing = Math.atan2(
      numericPoses[i].y - numericPoses[i-1].y, 
      numericPoses[i].x - numericPoses[i-1].x
    ) * 180 / Math.PI;
    turn_to_walk = normalizeAngleDeg(currentBearing - prevBearing);
  }

  instructions.push({
    step: i + 1,
    coordinate_index_from: C.coordinate_index,
    coordinate_index_to: F.coordinate_index,
    from_type: C.type,
    to_type: F.type,
    turn_to_walk_degrees: turn_to_walk.toFixed(1),
    walk_distance_meters: distance.toFixed(3),
    is_final_step: (i === numericPoses.length - 2)
  });
}

function normalizeAngleDeg(angle) {
  while (angle > 180) angle -= 360;
  while (angle < -180) angle += 360;
  return angle;
}

return [{ json: { instructions } }];

// Get input data from n8n
const rawInput = $input.all()[0].json;
// Convert object to array if needed
let inputData;
if (Array.isArray(rawInput)) {
  inputData = rawInput;
} else {
  // If it's an object with numeric keys, convert to array
  inputData = Object.values(rawInput);
}
// Helper function to parse coordinate values (handles both strings and numbers)
function parseCoord(value) {
  return typeof value === 'string' ? parseFloat(value) : value;
}
// Helper function to calculate Euclidean distance
function distance(p1, p2) {
  const dx = parseCoord(p1.x) - parseCoord(p2.x);
  const dy = parseCoord(p1.y) - parseCoord(p2.y);
  return Math.sqrt(dx * dx + dy * dy);
}
// Extract locations
const currentLocation = inputData[0];
const targetLocation = inputData[1];
const allPoints = inputData.slice(2);
// Create array of all nodes
const allNodes = [currentLocation, ...allPoints, targetLocation];
// Build graph by connecting each node to its K nearest neighbors
const K = 5; // Connect each point to its 5 nearest neighbors
const graph = new Map();
for (let i = 0; i < allNodes.length; i++) {
  // Calculate distances to all other nodes
  const distances = [];
  for (let j = 0; j < allNodes.length; j++) {
    if (i !== j) {
      distances.push({ idx: j, dist: distance(allNodes[i], allNodes[j]) });
    }
  }

  // Sort by distance and take K nearest
  distances.sort((a, b) => a.dist - b.dist);
  const neighbors = distances.slice(0, K);

  graph.set(i, neighbors);
}
// A* algorithm for shortest path
const startIdx = 0;
const endIdx = allNodes.length - 1;
const openSet = new Set([startIdx]);
const cameFrom = new Map();
const gScore = new Array(allNodes.length).fill(Infinity);
gScore[startIdx] = 0;
const fScore = new Array(allNodes.length).fill(Infinity);
fScore[startIdx] = distance(allNodes[startIdx], allNodes[endIdx]);
while (openSet.size > 0) {
  // Get node with lowest fScore
  let current = null;
  let lowestF = Infinity;
  for (const idx of openSet) {
    if (fScore[idx] < lowestF) {
      lowestF = fScore[idx];
      current = idx;
    }
  }

  if (current === endIdx) {
    // Reconstruct path
    const path = [current];
    while (cameFrom.has(current)) {
      current = cameFrom.get(current);
      path.unshift(current);
    }

    // Convert to coordinates and return
    return path.map(idx => allNodes[idx]);
  }

  openSet.delete(current);

  // Check all neighbors
  const neighbors = graph.get(current) || [];
  for (const { idx: neighbor, dist: edgeDist } of neighbors) {
    const tentativeGScore = gScore[current] + edgeDist;

    if (tentativeGScore < gScore[neighbor]) {
      cameFrom.set(neighbor, current);
      gScore[neighbor] = tentativeGScore;
      fScore[neighbor] = gScore[neighbor] + distance(allNodes[neighbor], allNodes[endIdx]);
      openSet.add(neighbor);
    }
  }
}
// No path found - return empty or original points
return [currentLocation, targetLocation];

const instructions = $input.item.json.instructions || [];
const MIN_TURN_DEG = 15;
const segments = [];

for (const inst of instructions) {
  const turn1 = parseFloat(inst.turn_to_walk_degrees);
  const dist = parseFloat(inst.walk_distance_meters);

  // Add alignment turn (if significant)
  if (!isNaN(turn1) && Math.abs(turn1) >= MIN_TURN_DEG) {
    segments.push({
      type: 'turn',
      angle: turn1,
      coordinate_index: inst.coordinate_index_from,
      step: inst.step,
      from_type: inst.from_type
    });
  }

  // Add walk (if significant distance)
  if (!isNaN(dist) && dist > 0.1) {
    segments.push({
      type: 'walk',
      distance: dist,
      coordinate_index_from: inst.coordinate_index_from,
      coordinate_index_to: inst.coordinate_index_to,
      step: inst.step,
      from_type: inst.from_type,
      to_type: inst.to_type
    });
  }

  // Add final orientation turn (placeholder - using 0 since not provided)
  const turn2 = parseFloat(inst.turn_at_dest_degrees) || 0;
  if (inst.is_final_step && Math.abs(turn2) >= MIN_TURN_DEG) {
    segments.push({
      type: 'turn',
      angle: turn2,
      coordinate_index: inst.coordinate_index_to,
      is_final_orientation: true,
      step: inst.step
    });
  }
}

return [{ json: { segments } }];

