            "url": $json.session.image || ""
          }
        }
      ]
    }
  ],
  "response_format": {
    "type": "json_schema",
    "json_schema": {
      "name": "chat",
      "schema": {
        "type": "object",
        "properties": {
          "visual_reasoning": {
            "type": "string",
            "description": "A short internal check of whether the user's question can be answered from the image. If not, state why."
          },
          "pointers": {
            "type": "string",
            "description": "A brief response to the user's question, using the image if needed."
          },
          "visual_data": {
            "type": "string",
            "description": "A detailed, objective description of the visual elements relevant to the question."
          }
        },
        "required": ["visual_reasoning", "pointers", "visual_data"],
        "additionalProperties": false
      }
    }
  }
}
}}

